import time
import logging
import paramiko
from taf.internal.managedobject import ManagedObject
from taf.internal.portforwarding.exceptions import ExecutionError, TimeoutError
from taf.internal.portforwarding.network import Address


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SshConnection(ManagedObject):

    LISTEN_RETRIES = 3
    LISTEN_WAIT_TIME = 3

    DEFAULT_TIMEOUT = 10

    def __init__(self,
                 user,
                 password,
                 host=None,
                 port=22,
                 ssh_forwarding=None,
                 pkey=None,
                 key_filename=None,
                 timeout=None,
                 **kwargs):
        super(SshConnection, self).__init__(**kwargs)
        self._host = host
        self._user = user
        self._password = password
        self._port = port
        self._pkey = pkey
        self._key_filename = key_filename
        self._timeout = timeout or self.DEFAULT_TIMEOUT

        self._ssh_forwarding = ssh_forwarding
        if self._ssh_forwarding:
            self.add_prerequisite(self._ssh_forwarding)

        self._ssh_client = self._create_ssh_client()
        self._transport = None
        self._invoke_shell = None

    @property
    def ssh_forwarding(self):
        return self._ssh_forwarding

    @ssh_forwarding.setter
    def ssh_forwarding(self, value):
        self._ssh_forwarding = value

    @property
    def address(self):
        return Address(host=self._host, port=self._port)

    @property
    def host(self):
        return self._host

    @property
    def port(self):
        return self._port

    @property
    def user(self):
        return self._user

    @property
    def password(self):
        return self._password

    @property
    def pkey(self):
        return self._pkey

    @property
    def key_filename(self):
        return self._key_filename

    @staticmethod
    def _create_ssh_client():
        ssh_client = paramiko.SSHClient()
        ssh_client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        return ssh_client

    def _setup(self):
        logger.debug("setup ssh connection host={}".format(self._host))
        config = dict(
            username=self._user,
            password=self._password,
            pkey=self._pkey,
            key_filename=self._key_filename)

        if self._ssh_forwarding:
            config.update(
                sock=self._ssh_forwarding.create_channel(),
                hostname=None)
        else:
            config.update(
                hostname=self._host,
                port=self._port)

        self._ssh_client.connect(**config)
        logger.debug("ssh connect: %r successfully", config)

    def invoke_shell(self):
        return self._ssh_client.invoke_shell()

    def invoke_shell_execute(self, command, invoke_shell=None, wait_time=3):
        if not invoke_shell:
            if not self._invoke_shell:
                self._invoke_shell = self._ssh_client.invoke_shell()
            invoke_shell = self._invoke_shell

        invoke_shell.send("{}\n".format(command))
        time.sleep(wait_time)
        return self._invoke_shell_read_output(invoke_shell)

    def _invoke_shell_read_output(self, invoke_shell):
        output = ""
        while invoke_shell.recv_ready():
            received = invoke_shell.recv(65535)
            if isinstance(received, bytes):
                received = bytes.decode(received)
            output += received
        return output

    def execute(self, command):
        logger.debug("execute command: {!r}".format(command))
        stdin, stdout, stderr = self._ssh_client.exec_command(command)
        exit_status = stdin.channel.recv_exit_status()
        stdout_data = stdout.read()
        stderr_data = stderr.read()
        if exit_status != 0 or stderr_data:
            raise ExecutionError(
                stdout_data=stdout_data,
                stderr_data=stderr_data,
                exit_status=exit_status)
        logger.debug("stdout_data: {!r}".format(stdout_data))
        return stdout_data

    def start(self, command, use_tty=False):
        logger.debug("start command: {!r}".format(command))
        stdin, stdout, stderr = self._ssh_client.exec_command(
            command=command,
            get_pty=use_tty)
        return stdin, stdout, stderr

    def get_forwarding_channel(self, host, port):
        logger.debug("get forwarding channel to {}:{}".format(host, port))
        transport = self._ssh_client.get_transport()
        return transport.open_channel(
            kind="direct-tcpip",
            dest_addr=(host, port),
            src_addr=("0,0,0,0", 0))

    def request_port_forward_and_return_transport(self, forward_port):
        logger.debug("request port forward to {}:{}".format(self._host, forward_port))
        self._transport = self._ssh_client.get_transport()
        self._transport.request_port_forward(self._host, forward_port)
        return self._transport

    def wait_until_listen(self, host, port):
        """
        use "ss -aptun" command to check if the port is listened.
        Netid   State       Recv-Q  Send-Q  Local Address:Port  Peer Address:Port
        tcp     ESTAB       0       0       10.57.157.8:22      10.57.157.8:33474
        tcp     CLOSE-WAIT  1       0       127.0.0.1:43132     127.0.0.1:42923
        ...
        """
        for _ in range(self.LISTEN_RETRIES):
            try:
                response = self.execute(
                    command=(
                        "ss -ptnl |"
                        'egrep -c "{host}:{port}|127.0.0.1:{port}"').format(
                            host=host,
                            port=port))
                if int(response.strip()) != 1:
                    raise ExecutionError(response)
                break
            except ExecutionError as exception:
                logger.debug(repr(exception))
                time.sleep(self.LISTEN_WAIT_TIME)
        else:
            raise TimeoutError(
                "listen at {host}:{port} on host {ssh_host}, "
                "retries={retries}, "
                "wait_time={wait_time}".format(
                    host=host,
                    port=port,
                    ssh_host=self._host,
                    retries=self.LISTEN_RETRIES,
                    wait_time=self.LISTEN_WAIT_TIME))

    def _teardown(self):
        logger.debug("teardown ssh connection {}:{}".format(self.host, self.port))
        if self._invoke_shell:
            self._invoke_shell.close()
        self._ssh_client.close()
